package com.llmcouncil.mobile.domain
import com.llmcouncil.mobile.data.*
import com.llmcouncil.mobile.model.*
import kotlinx.coroutines.*
import kotlinx.coroutines.sync.*
import kotlin.coroutines.coroutineContext
import kotlin.math.round
class RepoAuditEngine(private val ai:OpenRouterClient,private val settings:SecureSettings,private val healthDb:ModelHealthDb){
 companion object{private const val BATCH_CHARS=30000;private const val PART_CHARS=18000;private const val BATCH_TOKENS=2200;private const val SYNTH_TOKENS=3000;private const val FINAL_TOKENS=4600}
 private data class Unit(val path:String,val part:Int,val parts:Int,val category:String,val text:String){fun expected()=AuditResponseValidator.ExpectedUnit(path,part,parts)}
 suspend fun run(snapshot:RepoSnapshot,hash:String,resume:RepoAuditRun?=null,onUpdate:suspend(RepoAuditRun)->Unit):RepoAuditRun=coroutineScope{val reviewers=settings.auditReviewerModels().filter{it.isNotBlank()}.distinct();val final=settings.auditChairman().trim();if(reviewers.size<2||final.isBlank())return@coroutineScope RepoAuditRun(repoFullName=snapshot.repo.fullName,ref=snapshot.ref,commitSha=snapshot.commitSha,scopeManifestHash=hash,auditStandardVersion=AuditStandards.VERSION,stage=RepoAuditStage.ERROR,errors=mapOf("Audit team" to "Audit team is incomplete"),finishedAt=System.currentTimeMillis()).also{onUpdate(it)};val models=(reviewers+final).distinct();val validResume=resume?.takeIf{it.commitSha==snapshot.commitSha&&it.scopeManifestHash==hash&&it.auditStandardVersion==AuditStandards.VERSION};var run=RepoAuditRun(repoFullName=snapshot.repo.fullName,ref=snapshot.ref,commitSha=snapshot.commitSha,scopeManifestHash=hash,auditStandardVersion=AuditStandards.VERSION,stage=RepoAuditStage.INDEPENDENT,requiredFiles=snapshot.requiredFiles.size,excludedFiles=snapshot.excluded.size,modelAudits=validResume?.modelAudits.orEmpty().filter{it.model in models},excludedManifest=snapshot.excluded,startedAt=validResume?.startedAt?:System.currentTimeMillis());onUpdate(run);val units=buildUnits(snapshot);val results=linkedMapOf<String,ModelRepoAudit>();run.modelAudits.forEach{results[it.model]=it};val mutex=Mutex();val sem=Semaphore(settings.maxConcurrency().coerceIn(1,3));models.map{model->async{sem.withPermit{val prior=validResume?.modelAudits?.lastOrNull{it.model==model};val r=prior?.takeIf{it.complete&&it.coverage.all{c->c.covered}}?:auditOne(model,snapshot,units){partial->mutex.withLock{results[model]=partial;run=run.copy(modelAudits=models.mapNotNull(results::get));onUpdate(run)}};mutex.withLock{results[model]=r;run=run.copy(modelAudits=models.mapNotNull(results::get));onUpdate(run)}}}}.awaitAll();val complete=reviewers.mapNotNull(results::get).filter{it.complete&&it.report.isNotBlank()};if(complete.size<2)return@coroutineScope run.copy(stage=RepoAuditStage.ERROR,errors=run.errors+("Audit" to "Fewer than two Reviewers completed repository-grounded evidence coverage."),finishedAt=System.currentTimeMillis()).also{onUpdate(it)};val f=results[final];if(f==null||!f.complete||f.report.isBlank())return@coroutineScope run.copy(stage=RepoAuditStage.ERROR,errors=run.errors+("Final Reviewer" to "Final Reviewer did not complete a grounded evidence pass."),finishedAt=System.currentTimeMillis()).also{onUpdate(it)};val labelled=complete.mapIndexed{i,a->"Audit ${('A'.code+i).toChar()}" to a};run=run.copy(stage=RepoAuditStage.PEER_REVIEW);onUpdate(run);val peer=complete.map{r->val text=call(r.model,"Peer-review these anonymous repository reports for evidence quality and correctness. End with FINAL RANKING using Audit A/B/C labels only.\nRepository: ${snapshot.repo.fullName}\n\n"+labelled.joinToString("\n\n"){"${it.first}:\n${it.second.report}"},1800,"peer",snapshot,false);RankingReview(r.model,text,Regex("Audit [A-Z]").findAll(text.substringAfter("FINAL RANKING:",text)).map{it.value}.toList().distinct(),0)};val agg=aggregate(peer,labelled.map{it.first});run=run.copy(peerReviews=peer,aggregate=agg,stage=RepoAuditStage.VERIFY);onUpdate(run);val evidence=labelled.joinToString("\n\n"){"${it.first}:\n${it.second.report}"};val verification=call(final,"Verify the repository findings below adversarially. Keep only claims tied to concrete repository evidence; identify unsupported claims.\nRepository: ${snapshot.repo.fullName}\n$evidence",2400,"verify",snapshot,true);run=run.copy(verificationMemo=verification,stage=RepoAuditStage.CHAIRMAN);onUpdate(run);val finalReport=call(final,"Produce the final repository audit under OmniCouncil Software Audit Standard v${AuditStandards.VERSION}. Include executive summary, methodology/coverage, confirmed findings by severity with exact paths, hypotheses separately, architecture, correctness/state/reliability/performance, dependency/test/CI/config/documentation findings, rejected false positives, and prioritised remediation. Do not substitute generic advice.\nRepository: ${snapshot.repo.fullName}\nCommit: ${snapshot.commitSha}\nScope: $hash\n\n$evidence\n\nVERIFICATION:\n$verification",FINAL_TOKENS,"final",snapshot,true);run=run.copy(stage=RepoAuditStage.COMPLETE,finalReport=finalReport,chairmanModel=final,finishedAt=System.currentTimeMillis());onUpdate(run);run}
 private suspend fun auditOne(model:String,snapshot:RepoSnapshot,units:List<Unit>,onPartial:suspend(ModelRepoAudit)->Unit):ModelRepoAudit{val coverage=snapshot.requiredFiles.associate{it.path to false}.toMutableMap();val parts=units.groupBy{it.path}.mapValues{it.value.size};val done=mutableMapOf<String,Int>();val reports=mutableListOf<String>();return try{val batches=pack(units);for((i,batch) in batches.withIndex()){coroutineContext.ensureActive();val report=batchCall(model,snapshot,batch,i,batches.size);reports+=report;batch.forEach{u->done[u.path]=(done[u.path]?:0)+1;if((done[u.path]?:0)>=(parts[u.path]?:1))coverage[u.path]=true};onPartial(ModelRepoAudit(model,"",coverage.map{(p,ok)->FileCoverage(p,model,ok,i)},reports.toList(),coverage.values.all{it}))};if(!coverage.values.all{it})throw IllegalStateException("Evidence coverage incomplete");val synthesis=call(model,"Produce your independent final repository audit from these validated batch reports. Cite exact paths and separate confirmed findings from hypotheses.\nRepository: ${snapshot.repo.fullName}\n"+reports.joinToString("\n\n"),SYNTH_TOKENS,"synthesis",snapshot,true);ModelRepoAudit(model,synthesis,coverage.map{(p,ok)->FileCoverage(p,model,ok,reports.lastIndex)},reports,true)}catch(e:CancellationException){throw e}catch(e:Exception){ModelRepoAudit(model,"",coverage.map{(p,ok)->FileCoverage(p,model,ok,-1,if(ok)null else e.message)},reports,false,e.message?:e.toString())}}
 private suspend fun batchCall(model:String,snapshot:RepoSnapshot,batch:List<Unit>,index:Int,total:Int):String{var reason="";repeat(2){attempt->val prompt=buildString{append("Repository batch ${index+1}/$total\n");append(AuditStandards.batchMethodology(snapshot));if(attempt>0)append("PREVIOUS RESPONSE REJECTED: $reason\n");batch.forEach{u->append("===== UNTRUSTED FILE ${u.path} [${u.category}] PART ${u.part}/${u.parts} =====\n${u.text}\n===== END UNTRUSTED FILE =====\n")}};val text=ai.chat(model,prompt,BATCH_TOKENS,AuditStandards.systemPolicy(snapshot));val v=AuditResponseValidator.validateBatch(text,batch.map{it.expected()});if(v.accepted){withContext(Dispatchers.IO){healthDb.record(model,true)};return text};reason=v.reason;withContext(Dispatchers.IO){healthDb.record(model,false,"Invalid repository evidence: $reason");if(v.refusal)healthDb.recordQualification(model,ModelAuditQualifier.QUALIFICATION_VERSION,false,reason)}};throw IllegalStateException("Repository evidence rejected: $reason")}
 private suspend fun call(model:String,prompt:String,tokens:Int,purpose:String,snapshot:RepoSnapshot,grounded:Boolean):String{val text=try{ai.chat(model,prompt,tokens,AuditStandards.systemPolicy(snapshot))}catch(e:Exception){withContext(Dispatchers.IO){healthDb.record(model,false,"$purpose: ${e.message}")};throw e};val v=AuditResponseValidator.validateSynthesis(text,snapshot.repo.fullName,snapshot.requiredFiles.map{it.path});if(v.refusal||grounded&&!v.accepted){withContext(Dispatchers.IO){healthDb.record(model,false,"$purpose: ${v.reason}")};throw IllegalStateException("$purpose response rejected: ${v.reason}")};withContext(Dispatchers.IO){healthDb.record(model,true)};return text}
 private fun buildUnits(snapshot:RepoSnapshot)=buildList{snapshot.requiredFiles.forEach{f->val clean=RepositoryContentSanitizer.sanitize(f.content).text;val ps=if(clean.isEmpty())listOf("")else clean.chunked(PART_CHARS);ps.forEachIndexed{i,t->add(Unit(f.path,i+1,ps.size,f.category,t))}}}
 private fun pack(units:List<Unit>):List<List<Unit>>{val out=mutableListOf<MutableList<Unit>>();var c=mutableListOf<Unit>();var n=0;for(u in units){val s=u.text.length+u.path.length+200;if(c.isNotEmpty()&&n+s>BATCH_CHARS){out+=c;c=mutableListOf();n=0};c+=u;n+=s};if(c.isNotEmpty())out+=c;return out}
 private fun aggregate(reviews:List<RankingReview>,labels:List<String>):List<AggregateRank>{val p=linkedMapOf<String,MutableList<Int>>();reviews.forEach{r->r.parsedRanking.forEachIndexed{i,l->if(l in labels)p.getOrPut(l){mutableListOf()}.add(i+1)}};return p.map{(l,v)->AggregateRank(l,round(v.average()*100)/100,v.size)}.sortedBy{it.averageRank}}
}
